using Nexus.Service.Lighting.Rgb;

namespace Nexus.Service.Tests;

public class OpenRgbProtocolFixtureTests
{
    // Captured from a real OpenRGB headless server running on Windows with a
    // Razer Deathadder V2 Pro (Wireless) - controller index 0. Two captures
    // taken with different negotiated protocol versions so we exercise both
    // size cases (v5 = with zone_flags, v4 = without).
    private const string Controller0HexV5 =
        "";

    private const string Controller0HexV4 =
        "";

    [Fact]
    public void ParseControllerData_RealProtocolV5_Razer_Deathadder()
    {
        var bytes = HexToBytes(Controller0HexV5);
        var dev = OpenRgbProtocol.ParseControllerData(0, bytes, protocolVersion: 5);

        Assert.Equal(0, dev.Index);
        Assert.Equal("Razer Deathadder V2 Pro (Wireless)", dev.Name);
        Assert.Equal(6u, dev.Type); // mouse
        Assert.NotEmpty(dev.Zones);
        AssertLogoZoneBounds(dev);
    }

    [Fact]
    public void ParseControllerData_RealProtocolV4_Razer_Deathadder()
    {
        var bytes = HexToBytes(Controller0HexV4);
        var dev = OpenRgbProtocol.ParseControllerData(0, bytes, protocolVersion: 4);

        Assert.Equal(0, dev.Index);
        Assert.Equal("Razer Deathadder V2 Pro (Wireless)", dev.Name);
        Assert.Equal(6u, dev.Type); // mouse
        Assert.NotEmpty(dev.Zones);
        AssertLogoZoneBounds(dev);
    }

    [Theory]
    [InlineData(0xFFFFFFD8u)]
    [InlineData(0x80000000u)]
    [InlineData(0xFFFFFFFFu)]
    public void ParseControllerData_ZoneLedCountAboveIntMax_ParsesAsEmpty(uint wireCount)
    {
        var bytes = HexToBytes(Controller0HexV4);
        var nameAt = FindZoneName(bytes);
        var countAt = nameAt + 7 + 4 + 4 + 4;
        BitConverter.GetBytes(wireCount).CopyTo(bytes, countAt);

        var dev = OpenRgbProtocol.ParseControllerData(0, bytes, protocolVersion: 4);

        Assert.Equal(0, dev.Zones[0].LedCount);
    }

    private static int FindZoneName(byte[] bytes)
    {
        var needle = new byte[] { 0x05, 0x00, 0x4C, 0x6F, 0x67, 0x6F };
        return bytes.AsSpan().IndexOf(needle);
    }

    /// <summary>leds_min/leds_max sit between zone type and leds_count, so only a real capture pins their offsets.</summary>
    private static void AssertLogoZoneBounds(RgbDevice dev)
    {
        var logo = dev.Zones[0];
        Assert.Equal("Logo", logo.Name);
        Assert.Equal(1, logo.LedCount);
        Assert.Equal(1u, logo.LedsMin);
        Assert.Equal(1u, logo.LedsMax);
        Assert.True(logo.IsFixedSize);
    }

    private static byte[] HexToBytes(string hex)
    {
        hex = hex.Replace(" ", "").Replace("\n", "").Replace("\r", "");
        var bytes = new byte[hex.Length / 2];
        for (int i = 0; i < bytes.Length; i++)
            bytes[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
        return bytes;
    }
}
